package main

import "fmt"

func main() {
	var n int
	var x int
	fmt.Scanln(&n)
	a := make([]int, n)

	for i := 0; i < n; i++ {
		fmt.Scanln(&x)
		a[i] = x
	}
	fmt.Println(a)
}
